var xMin = -5.5, xMax = 5.5, yMin = -13.2, yMax = 14.2;
var curveColor = '#164a7a';
var orange = '#ff5a1f';
var teal = '#078f95';
var guideColor = '#777777';
var currentXProbe = -3;
var currentViewMode = 'Combined';
var hoverTarget = null;
var currentStep = 0;

function f(x) {
  return 3 * x + 1 + 2 / (x - 1);
}
function slant(x) {
  return 3 * x + 1;
}
function sampleCurve(a, b, n) {
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var x = a + (b - a) * i / n;
    var y = f(x);
    if (isFinite(y) && y >= yMin - 1.2 && y <= yMax + 1.2) pts.push({ x: x, y: y });
  }
  return pts;
}
function makeGuideData() {
  var x = currentXProbe;
  if (Math.abs(x - 1) < 0.05) x = x < 1 ? 0.9 : 1.1;
  var y = f(x);
  var ys = slant(x);
  if (!isFinite(y) || y < yMin || y > yMax || currentViewMode !== 'Combined') {
    return { horiz: [], slantGuide: [], probe: [] };
  }
  return {
    horiz: [{ x: x, y: y }, { x: 1, y: y }],
    slantGuide: [{ x: x, y: y }, { x: x, y: ys }],
    probe: [{ x: x, y: y }]
