}
function setDatasetData() {
  var g = makeGuideData();
  chart.data.datasets[0].data = [{ x: xMin, y: slant(xMin) }, { x: xMax, y: slant(xMax) }];
  chart.data.datasets[1].data = [{ x: 1, y: yMin }, { x: 1, y: yMax }];
  chart.data.datasets[2].data = sampleCurve(xMin, 0.985, 900);
  chart.data.datasets[3].data = sampleCurve(1.015, xMax, 900);
  chart.data.datasets[4].data = g.horiz;
  chart.data.datasets[5].data = g.slantGuide;
  chart.data.datasets[6].data = g.probe;
}
function applyVisibility() {
  var showCurve = currentViewMode === 'Combined' || currentViewMode === 'Curve only';
  var showAsymptotes = currentViewMode === 'Combined' || currentViewMode === 'Asymptotes only';
  var showProbe = currentViewMode === 'Combined' || currentViewMode === 'Curve only';
  chart.data.datasets[0].hidden = !showAsymptotes;
  chart.data.datasets[1].hidden = !showAsymptotes;
  chart.data.datasets[2].hidden = !showCurve;
  chart.data.datasets[3].hidden = !showCurve;
