  if (by < ca.top + 2) by = ca.top + 2;
  ctx.fillStyle = 'rgba(255,255,255,0.86)';
  ctx.strokeStyle = 'rgba(255,255,255,0.95)';
  ctx.lineWidth = 1;
  if (ctx.roundRect) {
    ctx.beginPath();
    ctx.roundRect(bx, by, w + 2 * pad, h + 2 * pad, pad);
    ctx.fill();
  } else {
    ctx.fillRect(bx, by, w + 2 * pad, h + 2 * pad);
  }
  ctx.fillStyle = color;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  for (var j = 0; j < lines.length; j++) ctx.fillText(lines[j], bx + pad, by + pad + fontSize + j * lineH);
  ctx.restore();
}
function drawItalicText(ctx, text, x, y, size) {
  ctx.save();
  ctx.font = 'italic bold ' + size + 'px serif';
  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
  ctx.restore();
}

var teachingPlugin = {
  id: 'asymptoteTeachingPlugin',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    var xs = chart.scales.x, ys = chart.scales.y;
    var s = Math.max(0.7, Math.min(1.25, Math.min(ca.width, ca.height) / 460));
    var fs = 13 * s;
    var tick = 4.5 * s;
    var arrow = 8 * s;
    var x0 = xs.getPixelForValue(0);
    var y0 = ys.getPixelForValue(0);
    ctx.save();
    ctx.strokeStyle = '#000000';
    ctx.fillStyle = '#000000';
    ctx.lineWidth = 1.25 * s;
    ctx.beginPath();
    ctx.moveTo(ca.left, y0);
    ctx.lineTo(ca.right, y0);
    ctx.moveTo(x0, ca.bottom);
    ctx.lineTo(x0, ca.top);
    ctx.stroke();
    drawArrowHead(ctx, ca.left + 14 * s, y0, ca.left, y0, '#000', arrow);
    drawArrowHead(ctx, ca.right - 14 * s, y0, ca.right, y0, '#000', arrow);
    drawArrowHead(ctx, x0, ca.top + 14 * s, x0, ca.top, '#000', arrow);
    drawArrowHead(ctx, x0, ca.bottom - 14 * s, x0, ca.bottom, '#000', arrow);

    ctx.font = fs + 'px serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (var x = -5; x <= 5; x++) {
      var px = xs.getPixelForValue(x);
      ctx.beginPath();
      ctx.moveTo(px, y0 - tick);
      ctx.lineTo(px, y0 + tick);
      ctx.stroke();
      if (x !== 0) ctx.fillText(String(x), px, y0 + 7 * s);
    }
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (var y = -12; y <= 12; y += 2) {
      var py = ys.getPixelForValue(y);
      ctx.beginPath();
      ctx.moveTo(x0 - tick, py);
      ctx.lineTo(x0 + tick, py);
      ctx.stroke();
      if (y !== 0) ctx.fillText(String(y), x0 - 7 * s, py);
    }
    drawItalicText(ctx, 'x', ca.right + 8 * s, y0 + 1 * s, 15 * s);
    drawItalicText(ctx, 'y', x0, ca.top - 10 * s, 15 * s);
    ctx.restore();
  },
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, ca = chart.chartArea;
    var xs = chart.scales.x, ys = chart.scales.y;
    var s = Math.max(0.7, Math.min(1.25, Math.min(ca.width, ca.height) / 460));
    var arrow = 10 * s;

    if (currentViewMode !== 'Asymptotes only') {
      function curveArrow(points, atEnd) {
        if (points.length < 2) return;
        var p = atEnd ? points[points.length - 1] : points[0];
        var q = atEnd ? points[points.length - 7] || points[0] : points[6] || points[points.length - 1];
        drawArrowHead(ctx, xs.getPixelForValue(q.x), ys.getPixelForValue(q.y), xs.getPixelForValue(p.x), ys.getPixelForValue(p.y), curveColor, arrow);
      }
      var leftPts = chart.data.datasets[2].data;
      var rightPts = chart.data.datasets[3].data;
      curveArrow(leftPts, false);
      curveArrow(leftPts, true);
      curveArrow(rightPts, false);
      curveArrow(rightPts, true);
    }

    if (currentViewMode !== 'Curve only') {
      drawBoxText(ctx, ['Slant asymptote', 'y = 3x + 1'], xs.getPixelForValue(1.95), ys.getPixelForValue(5.8), teal, 16 * s, 'left');
      drawBoxText(ctx, ['x = 1'], xs.getPixelForValue(1.23), ys.getPixelForValue(-8.4), orange, 16 * s, 'left');
    }

    if (currentViewMode !== 'Asymptotes only') {
      var x = currentXProbe;
      if (Math.abs(x - 1) < 0.05) x = x < 1 ? 0.9 : 1.1;
      var y = f(x);
      if (isFinite(y) && y >= yMin && y <= yMax) {
        var px = xs.getPixelForValue(x);
        var py = ys.getPixelForValue(y);
        var dist = Math.abs(x - 1);
        var off = y - slant(x);
        var side = x < 1 ? 14 * s : -132 * s;
        drawBoxText(ctx, ['|x − 1| = ' + dist.toFixed(2), 'offset = ' + off.toFixed(2)], px + side, py - 10 * s, '#333333', 12 * s, 'left');
      }
    }
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      { label: 'Slant asymptote y = 3x + 1', data: [], parsing: false, borderColor: teal, borderWidth: 2, borderDash: [7, 5], pointRadius: 0, tension: 0, clip: false },
      { label: 'Vertical asymptote x = 1', data: [], parsing: false, borderColor: orange, borderWidth: 2, borderDash: [7, 5], pointRadius: 0, tension: 0, clip: false },
      { label: 'Rational curve left branch', data: [], parsing: false, borderColor: curveColor, borderWidth: 3, pointRadius: 0, tension: 0.18 },
      { label: 'Rational curve right branch', data: [], parsing: false, borderColor: curveColor, borderWidth: 3, pointRadius: 0, tension: 0.18 },
      { label: 'distance to x = 1', data: [], parsing: false, borderColor: guideColor, borderWidth: 1.4, borderDash: [4, 4], pointRadius: 0, tension: 0 },
      { label: 'vertical offset from slant asymptote', data: [], parsing: false, borderColor: '#5f5f5f', borderWidth: 1.4, borderDash: [2, 3], pointRadius: 0, tension: 0 },
      { label: 'Probe point', data: [], parsing: false, showLine: false, pointRadius: 5, pointHoverRadius: 6, pointBackgroundColor: curveColor, pointBorderColor: '#ffffff', pointBorderWidth: 1.5 }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false }
    },
    layout: { padding: { left: 10, right: 18, top: 18, bottom: 12 } },
    scales: {
      x: { type: 'linear', min: xMin, max: xMax, grid: { display: false }, border: { display: false }, ticks: { display: false } },
      y: { type: 'linear', min: yMin, max: yMax, grid: { display: false }, border: { display: false }, ticks: { display: false } }
    },
    elements: { line: { fill: false, capBezierPoints: true } }
  },
  plugins: [teachingPlugin]
});
window.__markRendered();

function refreshFigure() {
  if (!chart) return;
  setDatasetData();
  applyVisibility();
  chart.update('none');
}
function update_xProbe(v) {
  if (Math.abs(v - 1) < 0.05) {
    v = currentXProbe < 1 ? 0.9 : 1.1;
    document.getElementById('xProbeInput').value = String(v);
    document.getElementById('xProbeVal').value = String(v);
  }
  currentXProbe = v;
  refreshFigure();
}
function toggle_viewMode(value) {
  currentViewMode = value === true ? 'Combined' : String(value || 'Combined');
  var input = document.getElementById('viewModeInput');
  if (input && input.value !== currentViewMode) input.value = currentViewMode;
  refreshFigure();
}

var demoSteps = [
  {
    title: 'See the full relationship',
    narration: 'In the combined view, the dark blue rational curve is drawn with two dashed asymptotes. The orange line x = 1 controls the break in the graph, while the teal line y = 3x + 1 describes the diagonal end behavior.',
    state: { viewMode: 'Combined', xProbe: -3 }
  },
  {
    title: 'Approach the vertical asymptote',
    narration: 'Drag the probe toward x = 1 from either side. As the horizontal distance to x = 1 shrinks, the function values shoot upward or downward, showing local blow-up near the vertical asymptote.',
    state: { viewMode: 'Combined', xProbe: 0.8 }
  },
  {
    title: 'Move toward the ends',
    narration: 'Move the probe far left or far right. The point stays close to the dashed teal line, showing that y = 3x + 1 is the boundary that controls end behavior.',
    state: { viewMode: 'Combined', xProbe: 4 }
  },
  {
    title: 'Separate function from asymptotes',
    narration: 'Switch among curve-only, asymptotes-only, and combined views. The asymptotes guide the curve’s behavior, but neither dashed line is itself part of the rational function.',
    state: { viewMode: 'Curve only', xProbe: 4 }
  }
];
function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ': ' + step.title;
  document.getElementById('xProbeInput').value = String(step.state.xProbe);
  document.getElementById('xProbeVal').value = String(step.state.xProbe);
  document.getElementById('viewModeInput').value = step.state.viewMode;
  currentXProbe = step.state.xProbe;
  currentViewMode = step.state.viewMode;
  refreshFigure();
}
function prevStep() {
  applyStep(currentStep - 1);
}
function nextStep() {
  applyStep(currentStep + 1);
}

function pixelDistanceToLine(px, py, ax, ay, bx, by) {
  var vx = bx - ax, vy = by - ay, wx = px - ax, wy = py - ay;
  var c1 = vx * wx + vy * wy;
  var c2 = vx * vx + vy * vy;
  var t = c2 ? Math.max(0, Math.min(1, c1 / c2)) : 0;
  var dx = px - (ax + t * vx);
  var dy = py - (ay + t * vy);
  return Math.sqrt(dx * dx + dy * dy);
}
function detectTarget(evt) {
  var pos = Chart.helpers.getRelativePosition(evt, chart);
  var xs = chart.scales.x, ys = chart.scales.y;
  var ca = chart.chartArea;
  if (pos.x < ca.left || pos.x > ca.right || pos.y < ca.top || pos.y > ca.bottom) return null;

  var xp = xs.getPixelForValue(currentXProbe);
  var yp = ys.getPixelForValue(f(currentXProbe));
  if (currentViewMode !== 'Asymptotes only' && isFinite(yp) && Math.hypot(pos.x - xp, pos.y - yp) < 11) return 'probe';

  if (currentViewMode !== 'Curve only') {
    if (Math.abs(pos.x - xs.getPixelForValue(1)) < 7) return 'vertical';
    var dSlant = pixelDistanceToLine(pos.x, pos.y, xs.getPixelForValue(xMin), ys.getPixelForValue(slant(xMin)), xs.getPixelForValue(xMax), ys.getPixelForValue(slant(xMax)));
    if (dSlant < 7) return 'slant';
  }

  if (currentViewMode !== 'Asymptotes only') {
    var xv = xs.getValueForPixel(pos.x);
    if (Math.abs(xv - 1) > 0.07) {
      var yv = f(xv);
      if (isFinite(yv)) {
        var py = ys.getPixelForValue(yv);
        if (Math.abs(pos.y - py) < 8) return 'curve';
      }
    }
  }
  return null;
}
canvas.addEventListener('mousemove', function (evt) {
  hoverTarget = detectTarget(evt);
  canvas.style.cursor = hoverTarget ? 'pointer' : 'default';
  if (hoverTarget === 'probe') {
    showTooltip('Probe on f(x). Compare its horizontal distance to x = 1 with its vertical offset from y = 3x + 1.', evt);
  } else if (hoverTarget === 'vertical') {
    showTooltip('Vertical asymptote: x = 1 is not in the domain, and the curve blows up nearby.', evt);
  } else if (hoverTarget === 'slant') {
    showTooltip('Slant asymptote: y = 3x + 1 describes the curve’s end behavior.', evt);
  } else if (hoverTarget === 'curve') {
    showTooltip('Rational function: f(x) = 3x + 1 + 2/(x − 1).', evt);
  } else {
    hideTooltip();
  }
});
canvas.addEventListener('mouseleave', function () {
  hoverTarget = null;
  canvas.style.cursor = 'default';
  hideTooltip();
});
canvas.addEventListener('click', function () {
  if (hoverTarget === 'vertical') {
    showPopup('Vertical asymptote', 'The line x = 1 marks a forbidden input. As x approaches 1, the term 2/(x − 1) becomes very large in magnitude, so the graph shoots upward or downward.');
  } else if (hoverTarget === 'slant') {
    showPopup('Slant asymptote', 'The dashed teal line y = 3x + 1 controls end behavior. Far from x = 1, the fraction 2/(x − 1) is small, so the rational function looks more and more like this line.');
  } else if (hoverTarget === 'probe') {
    showPopup('Probe point', 'Move the slider to test both ideas. Near x = 1, distance to the vertical asymptote matters most; far left or right, the offset from the slant asymptote becomes small.');
  } else if (hoverTarget === 'curve') {
    showPopup('Rational curve', 'This graph is f(x) = 3x + 1 + 2/(x − 1). Its two branches are separated by the vertical asymptote, but both branches follow the same slant asymptote toward the ends.');
  }
});

document.addEventListener('fig-resize', function () {
  if (chart) chart.resize();
});
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: A rational function whose numerator degree is one greater than its denominator can have a vertical asymptote controlling local blow-up and a slant asymptote controlling end behavior.
KEY INSIGHT (what students should walk away understanding): A vertical asymptote describes what happens near a forbidden x-value, while a slant asymptote describes what the rational function looks like as x goes far left or far right.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A rational function whose numerator degree is one greater than its denominator can have a vertical asymptote controlling local blow-up and a slant asymptote controlling end behavior.",
  "figureType": "line_plot",
  "elements": [
    "Cartesian coordinate plane with x-axis and y-axis, both with arrowheads",
    "x-axis labeled x with integer tick marks from -5 to 5",
    "y-axis labeled y with even-numbered tick marks from -12 to 12",
    "solid dark blue rational function curve with two disconnected branches",
    "left branch of the rational function, approaching the slant asymptote at far negative x, turning just below the x-axis near x = 0, then decreasing without bound as x approaches 1 from the left",
    "right branch of the rational function, increasing without bound just to the right of x = 1, reaching a minimum near y = 9, then rising while approaching the slant asymptote",
    "dashed orange vertical asymptote line x = 1 spanning the plotting window",
    "orange label x = 1 near the lower part of the vertical asymptote",
    "dashed teal slant asymptote line y = 3x + 1 crossing the graph diagonally upward",
    "teal label 'Slant asymptote y = 3x + 1' near the slant line",
    "movable probe point on the rational function curve",
    "guide segment from the probe point horizontally to the vertical asymptote x = 1",
    "guide segment from the probe point to the slant asymptote y = 3x + 1",
    "small numeric readouts for distance to x = 1 and vertical offset from y = 3x + 1"
  ],
  "interactions": [
    {
      "id": "xProbe",
      "type": "slider",
      "label": "Probe x-value",
      "range": [
        -5,
        5,
        0.1
      ],
      "default": -3,
      "teaches": "Moving a point along the curve shows that values near x = 1 are dominated by the vertical asymptote, while values far from x = 1 lie close to the slant asymptote y = 3x + 1"
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "View",
      "options": [
        "Curve only",
        "Asymptotes only",
        "Combined"
      ],
      "default": "Combined",
      "teaches": "The dashed asymptotes are not part of the function; they are reference boundaries that the curve approaches in different parts of the graph"
    }
  ],
  "demo_steps": [
    {
      "title": "See the full relationship",
      "narration": "In the combined view, the dark blue rational curve is drawn with two dashed asymptotes. The orange line x = 1 controls the break in the graph, while the teal line y = 3x + 1 describes the diagonal end behavior.",
      "state": {
        "viewMode": "Combined",
        "xProbe": -3
      }
    },
    {
      "title": "Approach the vertical asymptote",
      "narration": "Drag the probe toward x = 1 from either side. As the horizontal distance to x = 1 shrinks, the function values shoot upward or downward, showing local blow-up near the vertical asymptote.",
      "state": {
        "viewMode": "Combined",
        "xProbe": 0.8
      }
    },
    {
      "title": "Move toward the ends",
      "narration": "Move the probe far left or far right. The point stays close to the dashed teal line, showing that y = 3x + 1 is the boundary that controls end behavior.",
      "state": {
        "viewMode": "Combined",
        "xProbe": 4
      }
    },
    {
      "title": "Separate function from asymptotes",
      "narration": "Switch among curve-only, asymptotes-only, and combined views. The asymptotes guide the curve's behavior, but neither dashed line is itself part of the rational function.",
      "state": {
        "viewMode": "Curve only",
        "xProbe": 4
      }
    }
  ],
  "keyInsight": "A vertical asymptote describes what happens near a forbidden x-value, while a slant asymptote describes what the rational function looks like as x goes far left or far right.",
  "reconstructionNotes": "Use a single 2D Cartesian graph with a white background and black axes crossing at the origin. Plot the rational curve in dark blue, preferably matching f(x) = 3x + 1 + 2/(x - 1), with a gap at x = 1. Draw the vertical asymptote as a dashed orange line at x = 1 and label it in orange near the bottom. Draw the slant asymptote as a dashed teal line y = 3x + 1 and label it in teal near the middle-right of the graph. The left curve branch should hug the slant line at the lower left, crest slightly below the x-axis, and plunge downward near x = 1. The right branch should enter from above just right of x = 1, dip to a minimum around y = 9, and rise toward the upper right while tracking the slant line. In curve-only mode hide both dashed asymptotes and labels; in asymptotes-only mode hide the blue curve; in combined mode show all. The probe should avoid plotting exactly at x = 1 and may display an undefined warning or snap to the nearest valid side if the slider lands on the asymptote."
}

