function relativeCanvasPosition(evt) {
  var rect = canvas.getBoundingClientRect();
  var x = (evt.clientX - rect.left) * (canvas.width / rect.width);
  var y = (evt.clientY - rect.top) * (canvas.height / rect.height);
  return { x: x, y: y };
}
function pixelDistanceToLine(px, py, ax, ay, bx, by) {
  var vx = bx - ax, vy = by - ay, wx = px - ax, wy = py - ay;
  var c2 = vx * vx + vy * vy;
  var t = c2 ? Math.max(0, Math.min(1, (vx * wx + vy * wy) / c2)) : 0;
  var dx = px - (ax + t * vx);
  var dy = py - (ay + t * vy);
  return Math.sqrt(dx * dx + dy * dy);
}
function detectTarget(evt) {
  if (!chart || !chart.chartArea) return null;
  var pos = relativeCanvasPosition(evt);
  var xs = chart.scales.x, ys = chart.scales.y, ca = chart.chartArea;
  if (!xs || !ys || pos.x < ca.left || pos.x > ca.right || pos.y < ca.top || pos.y > ca.bottom) return null;

  if (probeVisible && currentViewMode !== 'Asymptotes only') {
    var xp = xs.getPixelForValue(currentXProbe);
    var yp = ys.getPixelForValue(f(currentXProbe));
    if (isFinite(yp) && Math.hypot(pos.x - xp, pos.y - yp) < 11) return 'probe';
  }

  if (currentViewMode !== 'Curve only') {
    if (Math.abs(pos.x - xs.getPixelForValue(1)) < 7) return 'vertical';
    var dSlant = pixelDistanceToLine(pos.x, pos.y, xs.getPixelForValue(xMin), ys.getPixelForValue(slant(xMin)), xs.getPixelForValue(xMax), ys.getPixelForValue(slant(xMax)));
    if (dSlant < 7) return 'slant';
  }

  if (currentViewMode !== 'Asymptotes only') {
    var xv = xs.getValueForPixel(pos.x);
    if (Math.abs(xv - 1) > 0.07) {
      var yv = f(xv);
      if (isFinite(yv)) {
        var py = ys.getPixelForValue(yv);
        if (Math.abs(pos.y - py) < 8) return 'curve';
      }
    }
  }
  return null;
}
